import "server-only";
import { db } from "@/lib/db";
import type { Prisma } from "@/generated/prisma/client";

// One statement sees the receipt transfer atomically, even outside a user lock.
export async function countQuotaUsage(
  userId: string,
  client: Pick<Prisma.TransactionClient, "$queryRaw"> = db,
  now = new Date(),
) {
  const since = new Date(now.getTime() - 86400000);
  // Ignore completed test deliveries only; queued and uncertain work still counts.
  const testing = process.env.NODE_ENV === "development";
  const [usage] = await client.$queryRaw<{ used: bigint }[]>`
    SELECT count(*) AS used FROM (
      SELECT s.id FROM "Send" s JOIN "Campaign" c ON c.id = s."campaignId"
      WHERE c."userId" = ${userId} AND (
        (s.status IN ('SENT', 'REPLIED') AND s."sentAt" >= ${since}
          AND (NOT ${testing} OR s."sentAt" > COALESCE(
            (SELECT "testingUsageResetAt" FROM "User" WHERE id = ${userId}), '-infinity'::timestamp)))
        OR (s.status = 'QUEUED' AND s."deliveryState" = 'READY')
        OR s."deliveryState" = 'ATTEMPTING'
        OR (s."deliveryState" = 'UNCERTAIN' AND COALESCE(s."attemptedAt", s."createdAt") >= ${since}))
      UNION ALL
      SELECT r.id FROM "DeliveryReceipt" r WHERE r."userId" = ${userId} AND r."sentAt" >= ${since}
        AND (NOT ${testing} OR r."sentAt" > COALESCE(
          (SELECT "testingUsageResetAt" FROM "User" WHERE id = ${userId}), '-infinity'::timestamp))
        AND (r."deliveryKey" IS NULL OR NOT EXISTS (
          SELECT 1 FROM "Send" s JOIN "Campaign" c ON c.id = s."campaignId"
          WHERE c."userId" = ${userId} AND s.id = r."deliveryKey"))
    ) deliveries`;
  return Number(usage.used);
}

export async function hasSuccessfulDelivery(
  client: Pick<Prisma.TransactionClient, "$queryRaw">,
  userId: string,
  email: string,
) {
  const [result] = await client.$queryRaw<{ exists: boolean }[]>`
    SELECT EXISTS (
      SELECT 1 FROM "Send" s JOIN "Campaign" c ON c.id = s."campaignId"
      WHERE c."userId" = ${userId} AND s."recipientEmail" = ${email} AND s.status IN ('SENT', 'REPLIED')
      UNION ALL
      SELECT 1 FROM "DeliveryReceipt" r WHERE r."userId" = ${userId} AND r."recipientEmail" = ${email}
    ) AS exists`;
  return result.exists;
}
